export function buildBridge() {
  const shards = [];
  const deck = [];
  for (let i = 0; i < 24; i++) {
    const x = -2.99 + i * 0.26;
    const g = x < 0 ? 2 : 3;
    deck.push({ p: [x, -0.07, 0], a: [1, 0, 0], L: 0.26, t: 0.14, glow: 0, g });
  }
  for (const s of deck) shards.push(s);
  for (const s of deck) {
    shards.push({ p: [s.p[0], s.p[1] + 0.075, s.p[2]], a: [1, 0, 0], L: 0.24, t: 0.02, glow: 1, g: s.g });
  }
  const pylonX = [-1.6, 1.6];
  const pylonG = [0, 5];
  for (let k = 0; k < 2; k++) {
    for (let i = 0; i < 6; i++) {
      shards.push({ p: [pylonX[k], 0.35 + i * 0.36, 0], a: [0, 1, 0], L: 0.34, t: 0.2, glow: 0, g: pylonG[k] });
    }
  }
  const offsets = [-1.35, -1.1, -0.85, -0.6, -0.35, -0.1, 0.1, 0.35, 0.6, 0.85, 1.1, 1.35];
  const cableG = [1, 4];
  for (let k = 0; k < 2; k++) {
    const xp = pylonX[k];
    for (let i = 0; i < offsets.length; i++) {
      const xa = xp + offsets[i];
      const za = i % 2 === 0 ? 0.28 : -0.28;
      const dx = xp - xa;
      const dy = 2.4 - 0.07;
      const dz = 0 - za;
      const L = Math.hypot(dx, dy, dz);
      shards.push({
        p: [(xp + xa) / 2, (2.4 + 0.07) / 2, za / 2],
        a: [dx / L, dy / L, dz / L],
        L,
        t: 0.03,
        glow: 0,
        g: cableG[k]
      });
    }
  }
  return { shards };
}
